const JTS190Z = WS('舊唐書/卷190中', 2027718); // 《舊唐書‧文苑列傳中》(陳子昂、賀知章)
const MOE_Q = (w) => `https://dict.revised.moe.edu.tw/search.jsp?md=1&word=${encodeURIComponent(w)}`;
const TCZ1 = WS('唐才子傳/卷1', 2673691); // 《唐才子傳》卷一(崔顥、王灣)
const TCZ3 = WS('唐才子傳/卷3', 2673689); // 元代辛文房《唐才子傳》卷三(王之渙、張繼)
