    gloss: [['浣溪沙', '詞牌名(詞的曲調名稱)。'], ['新詞', '新填的詞。'], ['舊亭臺', '原來的亭臺。'], ['幾時', '什麼時候。'], ['無可奈何', '沒有辦法。'],
      ['似曾相識', '好像曾經見過。'], ['香徑', '有花香的小路。'], ['徘徊', '來回走動。']],
