    about: '王安石,字介甫,北宋撫州臨川人。《宋史》說他「少好讀書，一過目終身不忘」,寫文章「動筆如飛」;後來當了宰相,罷相後判江寧府,《宋史》又說他「晚居金陵」。這首詩寫在何時,維基文庫這一頁和《宋史》都沒有寫。',
