    gloss: [['芙蓉樓', '送別的那座樓的名字。'], ['辛漸', '王昌齡的朋友。'], ['吳', '指古代吳國那一帶。'], ['平明', '天剛亮的時候。'], ['客', '指要離開的朋友辛漸。'], ['楚山', '楚地的山。'], ['冰心在玉壺', '比喻心地純潔、清白。']],
    note: '維基文庫收在〈芙蓉樓送辛漸二首〉,這是第一首(取自《全唐詩》卷143)。',
