    off: [],
    about: '這首詩的作者有兩種說法:一說是賈島,一說是孫革。賈島,字閬仙,唐朝詩人。元代辛文房《唐才子傳》說他騎驢時想到「僧推月下門」,又想改成「僧敲」,在驢背上做著推、敲的手勢,不知不覺衝撞了京兆尹韓愈的隊伍;韓愈想了很久說「敲字佳」,從此兩人成為朋友。',
