    gloss: [['郭', '外城。'], ['白水', '清澈的河水。'], ['一為別', '一旦分別。'], ['孤蓬', '隨風飄轉的蓬草,比喻遠行的人。'], ['征', '遠行。'], ['遊子', '離家遠行的人。'], ['故人', '老朋友。'], ['自茲', '從此、從這裡。'], ['蕭蕭', '馬叫的聲音。'], ['班馬', '離群的馬。']],
    note: '',
    off: [],
    about: '李白,字太白,唐朝詩人。《舊唐書‧文苑列傳下》說他是山東人,「少有逸才，志氣宏放，飄然有超世之心」:年輕時就很有才華,志向遠大,有超脫世俗的心。詩裡送的朋友是誰、在哪裡送別,詩和史書都沒寫。',
