    gloss: [['涼州詞', '唐代的曲調名稱,詩人依這個曲調寫詩。'], ['孤城', '孤單的城。'], ['仞', '古代長度單位;萬仞形容非常高。'], ['羌笛', '羌人吹的笛子。'], ['何須', '何必。'], ['楊柳', '指〈折楊柳〉這首曲子,古人常用來表達離別。'], ['度', '越過。'], ['玉門關', '古代通往西域的關口,在今敦煌西北(教育部辭典「玉門關」)。']],
