    gloss: [['咬定', '緊緊咬住不放。'], ['立根', '扎根。'], ['原', '本來。'], ['破巖', '裂開的岩石;巖同「岩」。'], ['磨', '折磨。'], ['擊', '打擊。'], ['堅勁', '堅強有力;勁念ㄐㄧㄥˋ。'], ['任', '任憑、隨便。'], ['爾', '你。']],
    note: '維基文庫〈竹石〉(鄭燮)原文照錄。',
    off: [],
    about: '鄭燮,清朝人。《清史稿‧藝術列傳三》說他「字板橋，江蘇興化人」,乾隆元年考中進士,當過山東濰縣知縣,「有惠政」:做了對百姓有好處的事;後來辭官賣畫,畫「蘭竹」:蘭花和竹子。這首詩寫在何時,維基文庫這一頁和《清史稿》都沒有寫。',
