    gloss: [['吟', '古代詩歌的一種。'], ['殘陽', '快要落山的太陽。'], ['瑟瑟', '原指一種碧綠的寶石(教育部辭典「瑟瑟」),這裡形容碧綠的顏色。'], ['可憐', '可愛。'], ['真珠', '珍珠。'], ['似', '像。']],
    note: '維基文庫〈暮江吟〉原文照錄。',
    off: [],
    about: '白居易,字樂天,唐朝詩人。《舊唐書》卷一百六十六說他「幼聰慧絕人」;十五六歲時帶著自己的文章去見著作郎顧況,顧況讀了,說:「吾謂斯文遂絕，復得吾子矣。」:我以為好文章已經斷絕了,沒想到又遇到你。這首詩寫在哪一年、哪一條江,維基文庫這一頁和《舊唐書》都沒有寫。',
