    gloss: [['當', '應當。'], ['人傑', '人中的豪傑。'], ['鬼雄', '鬼中的英雄。'], ['項羽', '人名,秦朝末年起兵的英雄;本站故事〈鴻門宴〉裡也有他。'], ['江東', '長江從蕪湖到南京這一段的南岸地區(教育部辭典「江東」)。']],
