    about: '李清照,號易安居士。《宋史‧文苑列傳六》在她父親李格非的傳裡寫她「詩文尤有稱于時」:詩文在當時特別有名。教育部辭典稱她「南宋女詞人」,並寫到她「南渡後」的生活;辭典寫她生於西元 1084 年。這首詩寫在什麼時候,維基文庫這一頁和《宋史》都沒寫,本站依規則掛在北宋,標「AI 推算」。',
