    about: '劉禹錫,字夢得,唐朝彭城人。《舊唐書》說他「精於古文，善五言詩」;晚年和白居易很要好,白居易稱讚他:「彭城劉夢得，詩豪者也。」這首詩寫在哪一年,維基文庫這一頁和《舊唐書》都沒有寫。',
