    gloss: [['汴水', '河川名,在河南滎陽縣,經山東入江蘇,注入淮河,也叫「汴河」(教育部辭典「汴水」)。'], ['泗水', '河川名,源出山東泗水縣(教育部辭典「泗水」)。'], ['瓜州', '即瓜洲,在江蘇江都縣南,長江北岸(教育部辭典「瓜洲」)。'], ['吳山', '吳地的山。'], ['悠悠', '長久不斷。'], ['倚樓', '靠在樓上。']],
